import memfs from 'memfs'
import { path, type FileSystem, zipDirectory } from '@servicenow/sdk-build-core'
import fs from 'fs'

export async function packMetadata(files: string[], rootDir?: string) {
    const vol = copyMetadataFolderFiles(files, '/', new memfs.Volume(), rootDir)
    const memFileSystem = memfs.createFsFromVolume(vol) as FileSystem

    const zipPath = await zipDirectory(memFileSystem, '/', '/metadata.zip')
    return vol.readFileSync(zipPath)
}

export async function createZip(fs: FileSystem, vol: memfs.Volume, files: string[]) {
    copyMetadataFolderFiles(files, '/', vol)
    return await zipDirectory(fs, '/', '/metadata.zip')
}

function copyMetadataFolderFiles(files: string[], copyToPath: string, vol: memfs.Volume, rootDir?: string) {
    const json = files.reduce<Record<string, string>>((acc, file) => {
        acc[path.join(copyToPath, file)] = fs.readFileSync(path.join(rootDir ?? __dirname, 'metadata', file), 'utf-8')
        return acc
    }, {})

    vol.fromJSON(json)
    return vol
}
